    if (sorted(s1).equals(sorted(s2)) == false) return false;

    // Use a HashMap to store the frequency of each character in s1 and s2
    Map<Character, Integer> map1 = new HashMap<>();
    Map<Character, Integer> map2 = new HashMap<>();
