    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

int longestConsecutiveSequence(TreeNode* root, int &longestPath) {
    if (root == NULL) {
        return 0;
    }
    int left = longestConsecutiveSequence(root->left, longestPath);
    int right = longestConsecutiveSequence(root->right, longestPath);
    int currPath = 1;
    if (root->left != NULL && root->left->val == root->val + 1) {
        currPath = max(currPath, left + 1);
    }
    if (root->right != NULL && root->right->val == root->val + 1) {
        currPath = max(currPath, right + 1);
    }
    longestPath = max(longestPath, currPath);
    return currPath;
}

int longestConsecutive(TreeNode* root) {
    int longestPath = 0;
    longestConsecutiveSequence(root, longestPath);
    return longestPath;
}
