// Function to find the k smallest pairs of numbers from two arrays
std::vector<std::vector<int>> kSmallestPairs(std::vector<int>& nums1, std::vector<int>& nums2, int k) {
    // Use a min-heap to store the pairs and their sums
    auto comp = [&nums1, &nums2](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        return nums1[a.first] + nums2[a.second] > nums1[b.first] + nums2[b.second];
    };
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, decltype(comp)> min_heap(comp);
    std::vector<std::vector<int>> result;

    // Initialize the min-heap with the first pair from each array
    if (!nums1.empty() && !nums2.empty()) {
        min_heap.emplace(0, 0);
    }

    // Extract the k smallest pairs
    while (k-- && !min_heap.empty()) {
        auto curr = min_heap.top();
        min_heap.pop();
        result.push_back({nums1[curr.first], nums2[curr.second]});
        // Add the next pair from the same array to the min-heap
