def path_sum_helper(node, target_sum, current_sum, memo):
    if node is None:
        return 0

    current_sum += node.val
    total_paths = memo.get((current_sum, target_sum), 0)
    total_paths += path_sum_helper(node.left, target_sum, current_sum, memo)
    total_paths += path_sum_helper(node.right, target_sum, current_sum, memo)
    memo[(current_sum, target_sum)] = total_paths
    return total_paths

def path_sum(root, target_sum):
    if root is None:
        return 0

    memo = {}
    return path_sum_helper(root, target_sum, 0, memo) + path_sum(root.left, target_sum) + path_sum(root.right, target_sum)
