int longestLine(const std::vector<std::vector<int>>& mat) {
    int rows = mat.size();
    int cols = mat[0].size();
    int max_length = 0;

    // Use a single dp array to store the lengths of all four directions
    std::vector<std::vector<int>> dp(rows, std::vector<int>(cols, 0));

    for (int r = 0; r < rows; ++r) {
        for (int c = 0; c < cols; ++c) {
            if (mat[r][c] == 1) {
                dp[r][c] = 1;
                if (r > 0) dp[r][c] += dp[r - 1][c];
                if (c > 0) dp[r][c] += dp[r][c - 1];
                if (r > 0 && c > 0) dp[r][c] += dp[r - 1][c - 1];
                if (r > 0 && c < cols - 1) dp[r][c] += dp[r - 1][c + 1];
                max_length = std::max(max_length, dp[r][c]);
            }
        }
    }
    return max_length;
