def backspaceCompare(s: str, t: str) -> bool:
    def process_string(string):
        i = len(string) - 1
        back = 0
        while i >= 0:
            if string[i] == '#':
                back += 1
            elif back > 0:
                back -= 1
            else:
                yield string[i]
