class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def subtreeWithAllDeepest(self, root: TreeNode) -> TreeNode:
        def find_deepest(node):
            if not node:
                return None, 0
            left, left_height = find_deepest(node.left)
            right, right_height = find_deepest(node.right)
            if left_height == right_height:
                return node, left_height + 1
            return (left, left_height + 1) if left_height > right_height else (right, right_height + 1)

        def dfs(node, depth, parent, depth_map):
            if not node:
                return
            if node not in depth_map:
                depth_map[node] = depth
            dfs(node.left, depth + 1, node, depth_map)
            dfs(node.right, depth + 1, node, depth_map)

        depth_map = {}
        dfs(root, 0, None, depth_map)
        deepest_node, _ = find_deepest(root)
        result = []
        stack = [deepest_node]
        while stack:
            node = stack.pop()
            if node in depth_map and depth_map[node] == max(depth_map.values()):
                result.append(node.val)
            if node.left:
                stack.append(node.left)
            if node.right:
                stack.append(node.right)
        return result
```

