    for (auto& connection : connections) {
        adj_list[connection[0]].push_back(connection[1]);
        adj_list[connection[1]].push_back(connection[0]);
    }

    // Perform DFS to count components and extra edges
    for (int i = 0; i < n; ++i) {
        if (!visited[i]) {
            components++;
            std::vector<int> stack = {i};

            while (!stack.empty()) {
                int current = stack.back();
                stack.pop_back();

                if (!visited[current]) {
                    visited[current] = true;
                    for (int neighbor : adj_list[current]) {
                        if (!visited[neighbor]) {
                            stack.push_back(neighbor);
                        } else {
                            extra_edges++;
                        }
                    }
                }
            }
        }
    }

    // Calculate minimum number of extra edges needed
    int extra_needed = components - 1;

    // Check if enough extra edges are available
    if (extra_edges >= extra_needed) {
        return extra_needed;
    }

    return -1;
