    // Iterate over all pairs of darts
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            // Calculate the distance between the two darts
            double dist = hypot(darts[j][0] - darts[i][0], darts[j][1] - darts[i][1]);

            // If the distance is greater than 2r, skip this pair
            if (dist > 2.0 * r) continue;

            // Calculate the angle between the two darts
            double angle = acos(dist / (2.0 * r));

            // Iterate over the two possible angles
            for (int k = 0; k < 2; k++) {
                // Calculate the new coordinates of the dart
                double loc_angle = angle * (k == 0 ? 1 : -1);
                double cx = darts[i][0] + r * (darts[j][0] - darts[i][0]) / dist * cos(loc_angle) - r * (darts[j][1] - darts[i][1]) / dist * sin(loc_angle);
