public:
    int val;
    ListNode* next;
    ListNode(int val, ListNode* next = nullptr) : val(val), next(next) {}
};

ListNode* sortedList(ListNode* head) {
    if (!head || !head->next) return head;

    ListNode* prev = head;
    ListNode* cur = head->next;

    while (cur) {
        if (cur->val < prev->val) {
            prev->next = cur->next;
            cur->next = head;
            head = cur;
            cur = prev;
        } else {
            prev = cur;
        }
        cur = cur->next;
    }
    return head;
}
```


