def num_special_subsequences(nums):
    zeros, ones, twos = 0, 0, 0
    mod = 1000000007
    for num in nums:
        if num == 0:
            zeros = (zeros + 1) % mod
        elif num == 1:
            ones = (ones + zeros) % mod
        else:
            twos = (twos + ones) % mod
    return twos
