def largest_even_sum(nums, k):
    evens = sorted([num for num in nums if num % 2 == 0], reverse=True)
    odds = sorted([num for num in nums if num % 2 != 0], reverse=True)

    sum = 0
    for _ in range(k):
        if evens:
            sum += evens.pop()

    for _ in range(0, k - 1, 2):
        if odds:
            first = odds.pop()
            if odds:
                second = odds.pop()
                sum += first + second

    return sum if sum % 2 == 0 else -1
