from heapq import heappop, heappush
from sys import maxsize

def dijkstra(src, adj):
    dist = [maxsize] * len(adj)
    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, u = heappop(pq)
        if d != dist[u]:
            continue
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heappush(pq, (dist[v], v))

    return dist

def min_weight_subgraph(n, edges, src1, src2, dest):
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    dist1 = dijkstra(src1, adj)
    dist2 = dijkstra(src2, adj)

    res = dist1[dest] + dist2[dest]
    for u, v, w in edges:
        res = min(res, dist1[u] + dist2[v] + w)
        res = min(res, dist1[v] + dist2[u] + w)

    return res if res != maxsize else -1

# Improved by using a more efficient data structure for the priority queue
def dijkstra(src, adj):
    dist = [maxsize] * len(adj)
    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, u = heappop(pq)
        if d != dist[u]:
            continue
        for v, w in adj[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                heappush(pq, (dist[v], v))

    return dist
