    public String compressString(String s) {
        int n = s.length();
        if (n <= 2) {
            return s;
        }
        StringBuilder sb = new StringBuilder();
        int count = 1;
        for (int i = 1; i < n; i++) {
            if (s.charAt(i) == s.charAt(i - 1)) {
                count++;
            } else {
                sb.append(s.charAt(i - 1)).append(count);
                count = 1;
            }
        }
