def minHeightJump(nums, costs):
    n = len(nums)
    dp = [float('inf')] * n

    dp[0] = 0
    for i in range(1, n):
        for j in range(i - 1, -1, -1):
            if ((nums[j] <= nums[i] and (j == 0 or nums[j - 1] < nums[i])) or (nums[j] > nums[i] and (j == 0 or nums[j - 1] >= nums[i]))):
