    int n = nums.size();
    std::vector<int> answer(n);
    int orSum = 0;

    for (int i = 0, j = 0; i < n; ++i) {
        orSum |= nums[i];
        while ((orSum | nums[j]) == orSum) {
            orSum ^= nums[j++];
        }

        answer[i] = i - j + 2;
    }

    return answer;
}
