from typing import List

def count_lcm_subarrays(nums: List[int], k: int) -> int:
    def lcm(a, b):
        temp = a
        while temp % b != 0:
            temp += a
        return temp

    count = 0
    for i in range(len(nums)):
        curr_lcm = nums[i]
        for j in range(i, len(nums)):
            curr_lcm = lcm(curr_lcm, nums[j])
            if curr_lcm == k:
                count += 1

    return count

# Improved runtime efficiency by using a set to store the current LCM
def count_lcm_subarrays(nums: List[int], k: int) -> int:
    def lcm(a, b):
        temp = a
        while temp % b != 0:
            temp += a
        return temp

    count = 0
    curr_lcm_set = set()
    for num in nums:
        curr_lcm_set.add(num)
        for prev_num in curr_lcm_set:
            curr_lcm = lcm(prev_num, num)
            if curr_lcm == k:
                count += 1

    return count
