def maximumChemistry(skill):
    total_sum = sum(skill)
    target_sum = total_sum // 2
    if total_sum % 2 == 1:
        return -1

    dp = {0: 1}
    max_chemistry = 0

    for s in skill:
        new_dp = {}
        for i in dp:
            if i + s <= target_sum:
                new_dp[i + s] = dp.get(i + s, 0) + dp[i]
                if i + s == target_sum:
                    max_chemistry += dp[i] * s
            if i + s > target_sum:
                new_dp[i] = dp.get(i, 0)
        dp = new_dp

    return max_chemistry if max_chemistry > 0 else -1
