#include <vector>
#include <algorithm>
using namespace std;

int maxStarSum(const vector<int>& vals, const vector<vector<int>>& edges, int k) {
    vector<int> adj[100000];
    int ans = -1e9;

    // Build adjacency list with edge weights
    for (const vector<int>& edge : edges) {
        adj[edge[0]].push_back(vals[edge[1]]);
        adj[edge[1]].push_back(vals[edge[0]]);
    }

    // Use a priority queue to keep track of the top k values
    priority_queue<int> pq;

    for (int i = 0; i < vals.size(); i++) {
        // Add the current value to the priority queue
        pq.push(vals[i]);

        // If the priority queue size exceeds k, remove the smallest value
        if (pq.size() > k) {
            pq.pop();
        }

        // Calculate the sum of the top k values
        int sum = vals[i];
        while (!pq.empty() && pq.size() < k) {
            sum += pq.top();
            pq.pop();
        }

        // Update the answer
        ans = max(ans, sum);
    }

    return ans;
}
