def length_of_cycle(n, queries):
    result = []
    for A, B in queries:
        depth_A, depth_B = 0, 0
        while A != B:
            if A < B:
                A, B = B, A
            A >>= 1
            depth_A += 1
        result.append(depth_A + depth_B)
    return result
