#include <vector>
#include <algorithm>

int kBigIndices(const std::vector<int>& nums, int k) {
    int n = nums.size();
    std::vector<int> left(n, 0), right(n, 0);

    // Calculate the number of elements to the left of each index that are greater than the current element
    for (int i = 1; i < n; ++i) {
        if (nums[i] > nums[i - 1])
            left[i] = left[i - 1] + 1;
    }

    // Calculate the number of elements to the right of each index that are greater than the current element
    for (int i = n - 2; i >= 0; --i) {
        if (nums[i] < nums[i + 1])
            right[i] = right[i + 1] + 1;
    }

    int count = 0;
    for (int i = 0; i < n; ++i)
        if (left[i] >= k && right[i] >= k)
            count++;

    return count;
}
