public int countFairPairs(int[] nums, int lower, int upper) {
    int n = nums.length;
    int fair_pairs = 0;
    Arrays.sort(nums);
    for (int i = 0; i < n; ++i) {
        int left = i + 1;
        int right = n - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (nums[i] + nums[mid] >= lower && nums[i] + nums[mid] <= upper) {
