            Long[] arr = new Long[n + 1];
            for (int i = 1; i <= n; ++i)
                arr[i] = new Long(in.nl());
            long mod = (int) 1e9 + 7;
            Arrays.sort(arr, 1, arr.length);
            long ans = 0;
            if (n % 2 == 0) {
                for (int i = n; i > n / 2; --i) {
                    ans += ((modexp(2, i - 1, mod) - modexp(2, n - i, mod)) * arr[i]);
                    ans = ans % mod;
