                    ans -= ((modexp(2, n - i, mod) - modexp(2, i - 1, mod)) * arr[i]);
                    ans = ans % mod;
                    if (ans < 0)
                        ans += mod;
                }
            } else {
                for (int i = n; i > n / 2 + 1; --i) {
                    ans += ((modexp(2, i - 1, mod) - modexp(2, n - i, mod)) * arr[i]);
                    ans = ans % mod;
