def iterative_dfs(graph, start, path=[]):
    visited = {}
    for i in graph:
        visited[i] = []
    q=[start]
    while q:
        v=q.pop(0)
        if not visited[v]:
            visited[v] = True
            path=path+[v]
            q=graph[v]+q
    return path

