def get_line():
    return [int(s) for s in input().strip().split()]

n, f = get_line()

kl = []
for _ in range(n):
    kl.append(get_line())


def get_extra(k, l):
    if l <= k:
        return 0
    if l <= 2*k:
        return l - k
    return k


extras = [get_extra(k, l) for k, l in kl]
if f == 0:
    extras_sum = 0
else:
    extras_sum = sum(sorted(extras)[-f:])
print(extras_sum + sum(min(k, l) for k, l in kl))
```


