def gcd(a, b):
    c = a % b
    return gcd(b, c) if c else b

def count_squares(n):
    count = 0
    for x in range(1, int(math.sqrt(n // 2)) + 1):
        for y in range(x + 1, int(math.sqrt(n - x * x)) + 1, 2):
            if gcd(x, y) == 1:
