	static int [] seg = {6, 2, 5, 5, 4, 5, 6, 3, 7, 6};

	public static int sumSeg (int i){

		int ans ;
		if (i >= 10) {
			ans = 0;
			while (i != 0){
				ans += seg[i % 10];
				i = i / 10;
			}
		}

		else
			ans = seg[i];


		return ans;
	}

