		int first = Integer.parseInt(st.nextToken());
		int last = Integer.parseInt(st.nextToken());
		int sum = 0;


		for (int i = first;i <= last;i++){
			sum += sumSeg(i);;
		}

		pw.println(sum);
		pw.flush();
		pw.close();
	}

}


