n, k = map(int, input().split())
s = input()

def goRight():
  i = k - 1
  while i < n - 1:
    print("RIGHT")
    i += 1
  i = n - 1
  while i >= 0:
    print("PRINT", s[i])
    if i:
      print("LEFT")
    i -= 1

def goLeft():
  i = k - 1
  while i > 0:
    print("LEFT")
    i -= 1
  i = 0
  while i < n:
    print("PRINT", s[i])
    if i != n - 1:
      print("RIGHT")
    i += 1

if ((n + 1) // 2 < k) or (k == n) and (k != 1):
  goRight()
else:
  goLeft()
