    input()
    st = input()
    ls = []
    for j in st:
        ls.append(get_mask(j))

    # Using bitwise operations to check for common characters
    common_chars = set(ls[0])
    for i in range(1, len(ls)):
        common_chars &= set(ls[i])

    if len(common_chars) > 0:
        print("YES")
    else:
        print("NO")
