from collections import deque

def solve(n, k, T, t):
    t.sort(key=lambda x: x[2])
    q = deque()
    q.append((1, set(range(1, n + 1)), 0))
    while q:
        h, w, r = q.popleft()
        if h > n:
            if T == 1:
                return r
            else:
                T -= 1
                continue
        for f, s, v in t:
            if f == h and s in w:
                q.append((h + 1, w - {s}, r + v))
    return -1

