        BufferedReader infile = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(infile.readLine());
        int N = Integer.parseInt(st.nextToken());
        int[] cnt = new int[200];
        while(N > 0) {
            int low = 3;
            int high = 200;
            while(low != high) {
                int mid = (low+high+1)/2;
                if(val(mid) > N) high = mid-1;
                else low = mid;
            }
            N -= val(low);
            cnt[low]++;
        }
        int max = 0;
        for(int v=1; v < 200; v++) {
            if(cnt[v] > 0) max = v;
        }
        StringBuilder sb = new StringBuilder("aa");
        for(int v=3; v < 200; v++) {
            if(max >= v) sb.append("a");
            while(cnt[v]-->0) sb.append("b");
        }
        sb.append(" aaab");
        System.out.println(sb);
    }
    public static long val(long x) {
        return x*(x-1)*(x-2)/6;
    }
}
