public class LogoTurtle {

	static char[] s;
	static int[][][] dp;

	static int solve(int i, int n, int dir) {
		if (i == s.length)
			return n == 0 ? 0 : -999999;
		if (dp[i][n][dir] != -1)
			return dp[i][n][dir];
		int ans = (s[i] == 'F' ? (dir == 0 ? 1 : -1) : 0)
