def gcd(a,b):
    if b==0:
        return a
    else:
        return gcd(b,a%b)


n, m = map(int, input().split(' '))
x = list(map(int, input().split(' ')))
p = list(map(int, input().split(' ')))
dx = [x[i+1]-x[i] for i in range(n-1)]
d = dx[0]
for i in dx:
    d = gcd(i, d)
divisors = set()
for i in range(1, int(d**0.5)+1):
    if d % i == 0:
        divisors.add(i)
        divisors.add(d//i)
for i in range(m):
    if d % p[i] == 0:
        print('YES')
        print(x[0], i+1)
        exit()
print('NO')
