def convert(n, base):
    a = "01"
    if n < base:
        if n % base >= 2:
            return False
        return a[n % base]
    else:
        if n % base >= 2:
            return False
        x = convert(n // base, base)
        if x:
            return x + a[n % base]
        return False


t = int(input())
for _ in range(t):
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    cnt = {}
    fl = True
    for i in a:
        x = convert(i, k)
        if x:
            for j in range(len(x)):
                if x[j] == '1':
                    if len(x) - j in cnt:
                        fl = False
                        break
